package net.hivel.islandsrpg.gui;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.data.PlayerData; import net.hivel.islandsrpg.stats.StatType; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.event.inventory.*; import org.bukkit.inventory.Inventory; import java.util.*;
public class StatsGui { private final IslandsRPGPlugin p; private final Map<Integer,StatType> slots=Map.of(10,StatType.MELEE,11,StatType.DEFENCE,12,StatType.SWORD,13,StatType.MAGIC,14,StatType.LUCK); public StatsGui(IslandsRPGPlugin p){this.p=p;} public void open(Player pl){Inventory inv=Bukkit.createInventory(null,27,ColorUtil.color("&8ꜱᴛᴀᴛꜱ")); PlayerData d=p.data().get(pl); for(var e:slots.entrySet()){StatType t=e.getValue(); inv.setItem(e.getKey(),new ItemBuilder(t.icon).name("&6"+t.display).lore(List.of("&7ᴄᴜʀʀᴇɴᴛ: &f"+d.stat(t),"&7ᴀᴠᴀɪʟᴀʙʟᴇ: &f"+d.statPoints,"","&eʟᴇꜰᴛ ᴄʟɪᴄᴋ &7+1","&eꜱʜɪꜰᴛ ʟᴇꜰᴛ &7+10","&bʀɪɢʜᴛ ᴄʟɪᴄᴋ &7ɪɴꜰᴏ")).build());} inv.setItem(22,new ItemBuilder(Material.NETHER_STAR).name("&6ᴀᴠᴀɪʟᴀʙʟᴇ ᴘᴏɪɴᴛꜱ").lore(List.of("&f"+d.statPoints)).build()); pl.openInventory(inv);} public void click(InventoryClickEvent e){e.setCancelled(true); if(!(e.getWhoClicked() instanceof Player pl))return; StatType t=slots.get(e.getSlot()); if(t==null)return; if(e.getClick().isRightClick()){pl.sendMessage(ColorUtil.color("&6ɪꜱʟᴀɴᴅꜱ&7: "+t.display+" improves RPG power."));return;} int amount=e.isShiftClick()?10:1; if(!p.stats().spend(pl,t,amount)) pl.sendMessage(ColorUtil.color(p.message("not-enough-points"))); open(pl);} }
